INSERT INTO news (kind, title, body) VALUES
 ('update', 'Novo evento: Blood Castle', 'O Blood Castle chegou! Junte Scroll of Archangel e Blood Bone do mesmo nível com uma Jewel of Chaos na Chaos Machine para criar o Cloak of Invisibility e fale com o Mensageiro do Arcanjo em Lorencia. Dá para entrar sozinho ou em grupo, sem party: derrote os monstros da ponte, derrube o Portão do Castelo e destrua a Estátua de Cristal para recuperar a Arma do Arcanjo. O Devil Square também aceita entrada individual.');
